const translations={en:{skip:'Skip to content',home:'Home',services:'Services',about:'About us',sectors:'Industries',team:'Our team',contact:'Contact',consult:'Consultation',heroLabel:'BUSINESS VISION. LEGAL STRENGTH.',hero1:'Legal advice',hero2:'that understands',hero3:'your business.',heroDesc:'For more than 10 years, protecting businesses and supporting their growth with strategic, dependable legal advice.',ourServices:'Our services',meetUs:'Meet CAMYA',heroFooter:'LAW, WITH A BROADER PERSPECTIVE.',discover:'Discover CAMYA',city:'MEXICO CITY',recognized:'RECOGNIZED BY',recognitionNote:'Experience that inspires confidence.',practiceLabel:'PRACTICE AREAS',practiceTitle:'Solutions for every<br>business challenge.',practiceIntro:'We combine legal specialization with a clear business perspective to prevent disputes, protect your interests and support your decisions.',practice1:'Litigation and<br>dispute resolution',practice1Desc:'Civil and commercial litigation, arbitration and private mediation. Strategies to address disputes and protect our clients’ interests.',practice2:'Corporate law and<br>business strategy',practice2Desc:'Corporate advice, corporate governance and contract review to support your operations and business decisions.',practice3:'Administrative<br>and regulatory law',practice3Desc:'Administrative and tax litigation, public procurement and regulatory matters related to business activity.',practice4:'Constitutional law<br>and amparo proceedings',practice4Desc:'Amparo proceedings, constitutional controversies and actions challenging the constitutionality of laws.',practice5:'Restructuring<br>and insolvency',practice5Desc:'Assistance in matters involving restructuring, insolvency proceedings and financial disputes.',practice6:'Real estate, energy<br>and the environment',practice6Desc:'Advice on real estate, environmental law and activities related to energy, oil and gas.',discuss:'Discuss this practice area',firmLabel:'THE FIRM',firmTitle1:'Beyond knowing',firmTitle2:'the law.',firmTitle3:'Understanding your world.',firmLead:'A firm of specialists, with a team that stays close to your business.',firmBody:'Our lawyers bring experience from leading law firms and multinational companies. This background enables us to handle strategic matters for domestic and international clients with an integrated perspective.',value1:'Strategy',value1Desc:'Every matter deserves a solution aligned with your objectives.',value2:'Integrity',value2Desc:'Ethics and professional rigor in every decision.',value3:'Partnership',value3Desc:'Diligent attention and understanding of your business.',sectorLabel:'INDUSTRY KNOWLEDGE',sectorTitle:'Your industry has its rules.<br>We understand them.',sectorIntro:'Legal advice begins with understanding the context in which each business operates.',sector1:'Financial services',sector2:'Technology',sector3:'Energy',sector4:'Real estate',sector5:'Manufacturing',sector6:'Commerce and consumer goods',teamLabel:'OUR TEAM',teamTitle:'Shared experience.<br>Personal commitment.',teamIntro:'Meet the partners who bring their specialization and professional experience to each matter.',profile:'View profile',partner:'Partner',partnerFemale:'Partner',contactLabel:'LET’S TALK',contactTitle:'Your next step,<br>with legal confidence.',contactIntro:'Tell us what your business needs. Let’s start by understanding your situation.',name:'Name',company:'Company',email:'Email address',message:'How can we help you',formNote:'The button opens your email application with a prepared message. Nothing is sent automatically.',compose:'Prepare email',footerLine:'Legal strength. Business vision.',privacy:'Privacy notice',terms:'Terms and conditions',footerDisclaimer:'The information on this site does not constitute legal advice.'}};
const originals=new Map([...document.querySelectorAll('[data-i18n]')].map(el=>[el,el.innerHTML]));
let lang='es';
const languageButton=document.querySelector('#language');
languageButton.addEventListener('click',()=>{lang=lang==='es'?'en':'es';document.documentElement.lang=lang==='es'?'es-MX':'en-US';originals.forEach((original,el)=>{el.innerHTML=lang==='es'?original:(translations.en[el.dataset.i18n]||original)});languageButton.innerHTML=lang==='es'?'ES <span>/ EN</span>':'EN <span>/ ES</span>';languageButton.setAttribute('aria-label',lang==='es'?'Switch to English':'Cambiar a español');document.title=lang==='es'?'CAMYA Abogados | Asesoría legal estratégica para empresas':'CAMYA Abogados | Strategic legal advice for businesses';document.querySelector('#navigation').setAttribute('aria-label',lang==='es'?'Navegación principal':'Main navigation');document.querySelector('.dialog-close').setAttribute('aria-label',lang==='es'?'Cerrar':'Close');updateMenuLabel()});
const menuButton=document.querySelector('#menu'),nav=document.querySelector('#navigation');
function updateMenuLabel(){menuButton.setAttribute('aria-label',lang==='es'?(nav.classList.contains('open')?'Cerrar menú':'Abrir menú'):(nav.classList.contains('open')?'Close menu':'Open menu'))}
menuButton.addEventListener('click',()=>{nav.classList.toggle('open');menuButton.setAttribute('aria-expanded',nav.classList.contains('open'));updateMenuLabel()});
nav.querySelectorAll('a').forEach(a=>a.addEventListener('click',()=>{nav.classList.remove('open');menuButton.setAttribute('aria-expanded','false');updateMenuLabel()}));
document.addEventListener('keydown',e=>{if(e.key==='Escape'){nav.classList.remove('open');menuButton.setAttribute('aria-expanded','false');updateMenuLabel()}});
const observer=new IntersectionObserver(entries=>{entries.forEach(e=>{if(e.isIntersecting){nav.querySelectorAll('a').forEach(a=>a.classList.toggle('active',a.getAttribute('href')==='#'+e.target.id))}})},{rootMargin:'-20% 0px -65% 0px',threshold:0});
document.querySelectorAll('main section[id]').forEach(section=>observer.observe(section));
const profiles={omar:{name:'Omar Cuéllar Gamboa',es:'Litigio civil y mercantil, reestructuras, concursos mercantiles y arbitraje.',en:'Civil and commercial litigation, restructuring, insolvency proceedings and arbitration.'},roberto:{name:'Roberto P. Serra Montes de Oca',es:'Derecho procesal constitucional, juicio de amparo y controversias constitucionales.',en:'Constitutional litigation, amparo proceedings and constitutional controversies.'},rafael:{name:'Rafael Benítez Fábregas',es:'Litigio civil, mercantil y familiar; derecho inmobiliario y corporativo; contratos y protección de datos.',en:'Civil, commercial and family litigation; real estate and corporate law; contracts and data protection.'},ilian:{name:'Ilian Munguía García',es:'Litigio administrativo y constitucional, derecho energético, ambiental y contrataciones públicas.',en:'Administrative and constitutional litigation, energy and environmental law, and public procurement.'},jose:{name:'José Luis Roldán Ortega',es:'Litigio civil, mercantil y constitucional.',en:'Civil, commercial and constitutional litigation.'}};
const dialog=document.querySelector('#profile-dialog');
function openDialog(html){document.querySelector('#dialog-content').innerHTML=html;dialog.showModal()}
document.querySelectorAll('[data-person]').forEach(button=>button.addEventListener('click',()=>{const key=button.dataset.person,p=profiles[key];openDialog(`<img class="dialog-photo" src="assets/${key}.webp" alt="${p.name}"><p class="dialog-specialty">${lang==='es'?'SOCIO · ÁREAS DE PRÁCTICA':'PARTNER · PRACTICE AREAS'}</p><h2>${p.name}</h2><p>${p[lang]}</p><a href="#contacto" class="button" id="dialog-contact">${lang==='es'?'Contactar a la firma':'Contact the firm'}</a>`);document.querySelector('#dialog-contact').addEventListener('click',()=>dialog.close())}));
document.querySelector('.dialog-close').addEventListener('click',()=>dialog.close());dialog.addEventListener('click',e=>{if(e.target===dialog){const rect=dialog.getBoundingClientRect();if(e.clientX<rect.left||e.clientX>rect.right||e.clientY<rect.top||e.clientY>rect.bottom)dialog.close()}});
document.querySelectorAll('[data-legal]').forEach(button=>button.addEventListener('click',()=>{const privacy=button.dataset.legal==='privacy';const title=lang==='es'?(privacy?'Aviso de privacidad':'Términos y condiciones'):(privacy?'Privacy notice':'Terms and conditions');const text=lang==='es'?(privacy?'Esta propuesta visual no almacena los datos introducidos en el formulario. Al preparar un correo, tu aplicación de correo gestiona el mensaje y su envío. Para la versión definitiva se incorporará el aviso de privacidad vigente y validado por CAMYA.':'La información presentada es de carácter general y no constituye asesoría legal ni establece una relación abogado-cliente. El contenido de esta propuesta visual deberá ser validado por CAMYA antes de su publicación definitiva.'):(privacy?'This visual proposal does not store the information entered in the form. Your email application manages the message and its delivery. The final version will include CAMYA’s approved, current privacy notice.':'The information is general in nature, does not constitute legal advice and does not establish an attorney-client relationship. CAMYA must approve the content of this visual proposal before final publication.');openDialog(`<h2>${title}</h2><p>${text}</p>`)}));
document.querySelector('#contact-form').addEventListener('submit',e=>{e.preventDefault();const data=new FormData(e.currentTarget);const subject=lang==='es'?'Consulta desde el sitio CAMYA':'Inquiry from the CAMYA website';const body=`${lang==='es'?'Nombre':'Name'}: ${data.get('name')}\n${lang==='es'?'Empresa':'Company'}: ${data.get('company')}\nEmail: ${data.get('email')}\n\n${data.get('message')}`;window.location.href='mailto:info@camya.mx?subject='+encodeURIComponent(subject)+'&body='+encodeURIComponent(body)});
